def solve_generic(grid):
    from collections import Counter
    out=[r[:] for r in grid]
    flat=[v for r in grid for v in r]
    bg=Counter(flat).most_common(1)[0][0]
    nonbg=[v for v in flat if v!=bg]
    if not nonbg:return out
    fg=Counter(nonbg).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    full=[i for i,r in enumerate(grid) if all(v==fg for v in r)]
    partial=[i for i,r in enumerate(grid) if any(v==fg for v in r) and not all(v==fg for v in r)]
    groups=[]
    for i in partial:
        if not groups or i>groups[-1][-1]+1: groups.append([i])
        else: groups[-1].append(i)
    # Two repeated multi-row patterns: align their horizontal translation.
    if len(groups)==2 and len(groups[0])==len(groups[1]) and len(groups[0])>1:
        A,B=groups
        best=None
        for s in range(-w+1,w):
            inter=union=0
            for ra,rb in zip(A,B):
                for c in range(w):
                    av=grid[ra][c]==fg
                    d=c+s
                    bv=(0<=d<w and grid[rb][d]==fg)
                    inter+=int(av and bv); union+=int(av or bv)
            key=(inter/union if union else 0,inter,-abs(s),s)
            if best is None or key>best: best=key
        s=best[3]
        if s>=0:
            src_rows,tgt_rows,delta=A,B,s
        else:
            src_rows,tgt_rows,delta=B,A,-s
        for rs,rt in zip(src_rows,tgt_rows):
            ref=[False]*w
            for c,v in enumerate(grid[rs]):
                if v==fg and 0<=c+delta<w: ref[c+delta]=True
            last_t=max((c for c,v in enumerate(grid[rt]) if v==fg),default=-1)
            last_r=max((c for c,x in enumerate(ref) if x),default=-1)
            # Fill missing foreground only in the right-hand tail.
            for c in range(last_t+1,w):
                if ref[c] and grid[rt][c]==bg: out[rt][c]=1
            # Mark an unmatched detached foreground tail in the target copy.
            if last_t>last_r:
                shared=max((c for c in range(w) if ref[c] and grid[rt][c]==fg),default=-1)
                if any(grid[rt][c]==bg for c in range(shared+1,last_t+1)):
                    for c in range(shared+1,last_t+1):
                        if grid[rt][c]==fg and not ref[c]: out[rt][c]=1
        return out
    # A single partial row can be completed from a full same-color reference line.
    for r in partial:
        last=max((c for c,v in enumerate(grid[r]) if v==fg),default=-1)
        for c in range(last+1,w):
            if any(grid[rr][c]==fg for rr in full): out[r][c]=1
    return out
